effect.shader:
void main(){
    float a=radians(angle);
    float side=acScreenNorm.x<0.5?-1.0:1.0;
    float dx=abs(acScreenNorm.x-0.5);
    float persp=1.0/(1.0+dx*sin(a)*2.0);
    float x=0.5+(acScreenNorm.x-0.5)/max(cos(a),0.1);
    float y=0.5+(acScreenNorm.y-0.5)*persp;
    if(x<0.0||x>1.0||y<0.0||y>1.0){gl_FragColor=vec4(0.0);return;}
    vec4 col=texture2DCv(inputImg.texture, vec2(x,y));
    col.rgb *= mix(1.0, 1.0-dx*sin(a), shade);
    gl_FragColor=col;
}
